/*
-----------------------------------------------------------------------
	Service CSS
-----------------------------------------------------------------------
*/

.static-media {
    padding-top: 90px;
    @media #{$xs-device} {
        padding-top: 80px;
    }
    @media #{$sm-device} {
        padding-top: 80px;
    }
    .media {
        padding-bottom: 30px;
        border-bottom: 1px solid #e5e5e5;
        .icon {
            align-self: center;
            color: #00213e;
            font-size: 48px;
        }

        .title {
            font-weight: 1000;
            text-transform: uppercase;
            text-align: center;
            line-height: 1;
            font-size: 20px;
            color: #00213e;
            margin-bottom: 10px;
            margin-left: 50px;
            @include min-screen(992) {
                font-size: 50px;
            }
        }
        p {
            color: #ff8c00;
            font-size: 20px;
            text-align: center;
            margin-left: 40px;
        }
    }
    .media-body {
        flex: 6;
    }
}

/*
-----------------------------------------------------------------------
	Service CSS
-----------------------------------------------------------------------
*/
.service-area {
    padding: 125px 0px;
    @media #{$lg-device} {
        padding: 100px 0px;
    }
    @media #{$sm-device} {
        padding: 80px 0px;
    }
    .section-title {
        margin-bottom: 90px;
        @media #{$lg-device} {
            margin-bottom: 70px;
        }
        @media #{$sm-device} {
            margin-bottom: 50px;
        }
    }
}

.service-item {
    .icon {
        color: $theme-color;
        font-size: 46px;
        line-height: 1;
        margin-bottom: 35px;
    }
    .content {
        position: relative;
        .service-name {
            color: #010101;
            font-size: 18px;
            letter-spacing: 0;
            margin-bottom: 18px;
        }
        p {
            font-size: 14px;
            line-height: 26px;
            margin-bottom: 30px;
        }
        .btn-link {
            color: $black;
            font-size: 14px;
            letter-spacing: 0.25px;
            i {
                color: $black-444;
                font-size: 17px;
                margin-left: 4px;
                position: relative;
                top: 1px;
            }
        }
    }
}

.service-style2 {
    border: 1px solid #e3e3e3;
    margin: 0;
    .service-item {
        border-bottom: 1px solid $white;
        border-right: 1px solid #ebebeb;
        padding: 50px 30px 35px 40px;
        position: relative;
        @include transition(0.3s);
        @media #{$lg-device} {
            padding: 40px 20px;
        }

        &:before {
            background-color: $theme-color;
            content: "";
            height: 0;
            left: 0;
            position: absolute;
            top: 0;
            width: 100%;
            @include transition(0.1s);
        }

        .icon {
            align-items: flex-end;
            display: flex;
            min-height: 48px;
            padding-left: 1px;
        }

        &:nth-child(1),
        &:nth-child(2),
        &:nth-child(3),
        &:nth-child(4) {
            border-bottom-color: #ebebeb;
        }
        &:nth-child(4),
        &:nth-child(8) {
            border-right-color: $white;
        }
        &:nth-child(5),
        &:nth-child(6) {
            @media #{$md-device} {
                border-bottom: 1px solid #ebebeb;
            }
        }

        &:hover {
            background-color: #f3f3f3;
            &:before {
                height: 4px;
            }
            .content {
                .btn-link {
                    color: $theme-color;
                }
            }
        }
    }
}

