.service-slider-container {
    margin-top: 161px;
    @media #{$lg-device} {
        margin-top: 131px;
    }
    @media #{$md-device} {
        margin-top: 106px;
    }
    @media #{$sm-device} {
        margin-top: 86px;
    }
    @media #{$xs-device} {
        margin: 66px auto 0;
        max-width: 300px;
    }
    @media (max-width: 461px) {
        margin-top: 55px;
    }
    .service-slider {
        &.service-category {
            .category-item {
                padding-top: 4px;
                .icon {
                    top: -17px;
                }
            }
        }
    }
}
