/*
-----------------------------------------------------------------------
  Common CSS
-----------------------------------------------------------------------
*/

.container {
    @media #{$xl-device} {
        max-width: 1170px;
    }
}
.bg-white {
    background-color: #ffffff;
}
.bg-gray {
    background-color: #f3f3f3;
}
.section-title {
    margin-bottom: 80px;
    @media #{$md-device} {
        margin-bottom: 70px;
    }
    @media #{$sm-device} {
        margin-bottom: 60px;
    }
    @media #{$xs-device} {
        margin-bottom: 50px;
    }
    p {
        color: #999999;
        font-size: 14px;
        font-weight: $font-weight-normal;
        letter-spacing: 0.3px;
        margin-bottom: 15px;
        text-transform: uppercase;
        @media #{$sm-device} {
            font-size: 12px;
            margin-bottom: 12px;
        }
    }
    .title {
        font-size: 48px;
        font-weight: $font-weight-light;
        letter-spacing: -1.377px;
        line-height: 1.1;
        margin-bottom: 25px;
        @media #{$lg-device} {
            font-size: 40px;
        }
        @media #{$sm-device} {
            font-size: 30px;
        }
        @media #{$xs-device} {
            font-size: 25px;
        }
        span {
            color: #00213e;
            font-weight: $font-weight-bold;
        }
    }
    .desc {
        margin-bottom: 55px;
        p {
            font-size: 14px;
            line-height: 30px;
            margin-bottom: 0;
            @media #{$sm-device} {
                br {
                    display: none;
                }
            }
        }
    }
    .separator-line {
        border-bottom: 1px solid $theme-color;
        display: block;
        margin: 0 auto 40px;
        width: 100px;
    }
    .list-style {
        li {
            color: $body-color;
            font-size: 14px;
            margin-bottom: 16px;
            padding-left: 29px;
            position: relative;
            i {
                color: $theme-color;
                font-size: 14px;
                left: 0;
                position: absolute;
                top: 5px;
            }
            &:last-child {
                margin-bottom: 0;
            }
        }
    }
    &.section-light {
        h5 {
            color: $white;
        }
        .title {
            color: $white;
        }
        .desc {
            p {
                color: $white;
            }
        }
        .separator-line {
            border-bottom-color: $white !important;
            &.separator-double {
                &:before {
                    border-bottom-color: $white !important;
                }
            }
        }
    }
}

.bg-img {
    background: no-repeat center center;
    background-size: cover;
    &.bg-img-top {
        background-position: top center;
    }
}

.site-wrapper-reveal {
    background-color: #ffffff;
    position: relative;
    overflow: hidden;
    z-index: 1;
}

.niceselect {
    float: inherit;
    .list {
        border-radius: 0;
        width: 100%;
    }
}

.line-hr {
    border-bottom: 1px solid #e2e2e2;
}

.lh-1 {
    line-height: 1;
}

.z-index-1 {
    z-index: 1;
}

.z-index-2 {
    z-index: 2;
}

.content-items-center {
    align-items: center;
    display: flex;
}

.justify-items-center {
    display: flex;
    justify-content: center;
}

.min-height-auto {
    min-height: auto !important;
}

.height-auto {
    height: auto !important;
}

.form-message.alert {
    margin-top: 10px;
}

.row-gutter-0 {
    [class*="col-"] {
        margin: 0;
        padding: 0;
    }
}

@media #{$md-device} {
    .md-text-center {
        text-align: center;
    }
}

@media #{$sm-device} {
    .sm-text-center {
        text-align: center;
    }
}

@media #{$xs-device} {
    .xs-w-100 {
        width: 100% !important;
    }
}

/*-------- Button Style Css --------*/

.btn-theme {
    background-color: #00213e;
    border-color: #00213e;
    border-radius: 0;
    color: $white;
    display: inline-block;
    font-weight: $font-weight-normal;
    font-size: 14px;
    line-height: 30px;
    min-height: 50px;
    padding: 10px 30px;
    position: relative;
    text-transform: uppercase;
    @include transition(0.3s);

    .icon {
        font-size: 14px;
        padding-left: 12px;
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        right: 15px;
    }

    &:hover,
    &:focus {
        background-color: #00213e;
        border-color: #00213e;
        color: $white;
    }

    &.btn-black {
        background-color: $black;
        border-color: $black;

        &:hover {
            background-color: $theme-color;
            border-color: $theme-color;
            color: $white;
        }
    }

    &.btn-white {
        background-color: $white;
        border-color: $white;
        color: $black-0e;

        &:hover {
            background-color: $black;
            border-color: $black;
            color: $white;
        }

        &.btn-border {
            background-color: transparent;
            border: 1px solid rgba($white, 0.5);
            color: $white;
            line-height: 29px;
            &:hover {
                background-color: $theme-color;
                border-color: $theme-color;
                color: $white;
            }
        }
    }

    &.btn-gray {
        background-color: $white-f4;
        border-color: $white-f4;
        color: $black-0e;

        &:hover {
            background-color: $theme-color;
            border-color: $theme-color;
            color: $white;
        }
    }

    &.btn-border {
        background-color: transparent;
        border: 1px solid $theme-color;
        color: $theme-color;
    }

    &.btn-round {
        border-radius: 25px;
        &.btn-slide {
            &:before {
                border-radius: 25px;
            }
        }
    }

    &.btn-lg {
        letter-spacing: 0.131px;
        padding: 14px 48px;
    }

    &.btn-slide {
        position: relative;
        z-index: 1;
        &:before {
            background-color: $theme-color3;
            content: "";
            height: 100%;
            left: 0;
            position: absolute;
            top: 0;
            width: 0;
            z-index: -1;
            @include transition(0.3s);
        }
        &:hover {
            &:before {
                width: 100%;
            }
        }
    }

    &.btn-size-md {
        height: 50px;
        min-width: 160px;
        text-align: center;
    }

    &.btn-size-lg {
        height: 50px;
        min-width: 180px;
        text-align: center;
    }

    &.btn-size-xl {
        height: 50px;
        min-width: 220px;
        text-align: center;
    }

    &.btn-size-xxl {
        height: 52px;
        min-width: 270px;
        text-align: center;
    }
}

.btn-link {
    color: $black;
    display: inline-block;
    font-weight: $font-weight-normal;
    font-size: 12px;
    letter-spacing: 1px;
    padding: 0;
    position: relative;
    text-decoration: none;
    text-transform: uppercase;
    @include transition(0.3s);
    &:hover {
        color: $theme-color;
        text-decoration: none;
    }
    span {
        & + .icon {
            color: $theme-color;
            font-size: 14px;
            padding-left: 17px;
            &:before {
                font-weight: 900;
            }
        }
    }
    &:focus {
        text-decoration: none;
    }
    &.btn-line {
        &:after {
            background-color: $theme-color;
            bottom: 0;
            content: "";
            height: 1px;
            right: 0;
            position: absolute;
            width: 0;
            @include transition(0.3s);
        }
        &:hover {
            color: $black;
            &:after {
                left: 0;
                width: 100%;
            }
        }
    }
    &.btn-dark {
        background-color: transparent;
        border: none;
        color: $black-0e;
        &:after {
            background-color: $black-0e;
            left: 0;
            width: 100%;
        }
        &:hover {
            color: $theme-color;
            &:hover {
                &:before {
                    background-color: $theme-color;
                }
                &:after {
                    background-color: $theme-color;
                }
            }
        }
    }
}

/*-------- Owl Carousel Style Css --------*/

.owl-carousel {
    &.owl-theme {
        .owl-nav {
            margin: 0;
            [class*="owl-"] {
                background-color: transparent;
                font-size: 24px;
                font-weight: $font-weight-black;
                margin: 0;
                @include transition(0.4s);
                &:hover {
                    color: $theme-color;
                }
            }
            .owl-prev {
                margin-right: 10px;
            }
            .owl-next {
                margin-left: 10px;
            }
        }
        &.owl-nav2 {
            .owl-nav {
                left: 0;
                position: absolute;
                right: 0;
                top: 50%;
                [class*="owl-"] {
                    position: absolute;
                    &.owl-prev {
                        left: 0;
                    }
                    &.owl-next {
                        right: 0;
                    }
                }
            }
        }
        .owl-dots {
            margin-top: 55px;
            .owl-dot {
                span {
                    background-color: #808080;
                    border: 1px solid #808080;
                    height: 10px;
                    margin: 5px 12px;
                    width: 10px;
                    @include transition(0.4s);
                }
                &.active,
                &:hover {
                    span {
                        background-color: $theme-color;
                        border-color: $theme-color;
                    }
                }
            }
        }
    }
    &.owl-dots-none {
        .owl-dots {
            display: none;
        }
    }
}

/*-------- Page Title Style Css --------*/

.page-title-area {
    .page-title-content {
        letter-spacing: 0;
        padding: 60px 0;
        .title {
            color: $black;
            font-size: 48px;
            font-weight: $font-weight-light;
            letter-spacing: -1.377px;
            line-height: 1.1;
            @media #{$lg-device} {
                font-size: 36px;
            }
            @media #{$sm-device} {
                font-size: 30px;
            }
            span {
                color: $theme-color;
                font-weight: $font-weight-bold;
            }
        }
        .bread-crumbs {
            color: $black-888;
            font-size: 15px;
            margin-bottom: 2px;
