.bread-crumbs {
    color: $body-color;
    font-size: 16px;
    a {
        color: $body-color;
        &:hover {
            color: $theme-color;
        }
    }
}

/*-------- Pagination Style Css --------*/

.pagination-area {
    padding: 82px 0 0;
    @media #{$md-device} {
        padding: 62px 0 0;
    }
    nav {
        .page-numbers {
            align-items: center;
            background-color: $white;
            border-radius: 5px;
            display: inline-flex;
            margin-bottom: 0;
            li {
                line-height: 1;
                margin-right: 36.57px;
                padding: 0;
                .page-number {
                    color: $black-999;
                    display: inline-block;
                    font-size: 18px;
                    font-weight: $font-weight-normal;
                    letter-spacing: 0;
                    line-height: 1;
                    &:hover {
                        color: $black;
                    }
                    &.current {
                        color: $black;
                        font-weight: $font-weight-bold;
                    }
                    &.prev {
                        border-radius: 0;
                        color: $black;
                        font-size: 14px;
                    }
                    &.next {
                        color: $black;
                        font-size: 22px;
                        &:hover {
                            color: $black;
                        }
                    }
                }
                &:first-child {
                    padding-left: 0;
                }
                &:last-child {
                    padding-right: 0;
                    margin-right: 0;
                }
            }
            &.page-numbers-style {
                box-shadow: 0px 10px 50px 0px rgba(171, 181, 189, 0.35);
            }
        }
    }
}

/*-------- Blockquote Style Css --------*/

.blockquote-area {
    background-size: cover;
    background-repeat: no-repeat;
    padding: 165px 0 140px;
    @media #{$sm-device} {
        padding: 122px 0 94px;
    }

    p {
        color: $white;
        font-size: 36px;
        line-height: 1.2;
        margin-bottom: 70px;
        @media #{$sm-device} {
            font-size: 24px;
        }
    }
    cite {
        .name {
            color: $theme-color;
            display: block;
            font-size: 16px;
            font-weight: $font-weight-normal;
            font-style: normal;
            margin-bottom: 5px;
            text-transform: uppercase;
        }
        .job {
            color: #9192a4;
            font-size: 14px;
        }
    }
}

/*-------- Accordian Style Css --------*/

.accordian-content {
    .accordion {
        .accordion-item {
            border: none;
            margin-bottom: 30px;
            overflow: visible;
            .accordion-header {
                padding: 0;
                .accordion-button {
                    align-items: center;
                    background-color: $white;
                    border: none;
                    border-radius: 5px;
                    box-shadow: none;
                    color: $white;
                    display: flex;
                    font-size: 14px;

                    font-weight: $font-weight-bold;
                    justify-content: space-between;
                    padding: 15px 30px;
                    position: relative;
                    text-align: left;
                    width: 100%;
                    z-index: 1;
                    @include transition(0.4s);
                    &:before {
                        background-color: $theme-color;
                        border-radius: 5px;
                        content: "";
                        height: 100%;
                        left: 0;
                        position: absolute;
                        top: 0;
                        width: 100%;
                        z-index: -1;
                        @include transition(0.4s);
                    }
                    &:after {
                        display: none;
                    }
                    .icon {
                        color: $white;
                        font-size: 14px;
                        @include transition(0.4s);
                        &.icon-plus {
                            display: none;
                        }
                    }
                    &.collapsed {
                        box-shadow: 0px 7px 30px 0px rgba(171, 181, 189, 0.35);
                        color: $black;
                        &:before {
                            background-color: $white;
                            background-image: none;
                        }
                        .icon {
                            color: $black;
                            &.icon-plus {
                                display: inline-block;
                            }
                            &.icon-minus {
                                display: none;
                            }
                        }
                        &:hover {
                            background-color: $white-f9;
                            &:before {
                                background-color: $white-f9;
                            }
                        }
                    }
                }
            }
            .accordion-body {
                line-height: 30px;
                padding: 34px 30px 16px;
            }
        }
        &.no-bg {
            .accordion-item {
                margin-bottom: 14px;
                .accordion-header {
                    .accordion-button {
                        background-color: transparent;
                        border-bottom: 1px solid #e1e1e1;
                        border-radius: 0;
                        color: $black;
                        padding: 0 0 20px 20px;
                        &:before {
                            display: none;
                        }
                        .icon {
                            color: $black;
                        }
                        &.collapsed {
                            box-shadow: none;
                            &:hover {
                                background-color: transparent;
                            }
                        }
                    }
                }
            }
            .accordion-collapse {
                border: none;
            }
            .accordion-body {
                padding: 20px 35px 14px 20px;
            }
        }
        &.accordion-style2 {
            .accordion-item {
                .accordion-header {
                    position: relative;
                    .icon {
                        font-size: 24px;
                        color: $black;
                        position: absolute;
                        right: 15px;
                        top: 50%;
                        transform: translateY(-50%);
                        &.opened {
                            display: none;
                        }
                    }
                    &.active {
                        & .title {
                            border: none;
                            color: $theme-color;
                            font-size: 18px;
                            @media (max-width: 767px) {
                                font-size: 14px;
                            }
                            font-weight: $font-weight-bold;
                            justify-content: normal;
                            line-height: 24px;
                            padding: 0 30px 13px 0;
                            @include transition(0.3s);
                            @media #{$xxs-device} {
                                padding: 0 10px 13px 0;
                            }
                        }
                        .closed {
                            display: none;
                        }
                        .opened {
                            display: block !important;
                        }
                    }
                    .title {
                        display: flex;
                        align-items: center;
                        text-align: left;
                        font-size: 18px;
                        line-height: 24px;
                        @media (max-width: 767px) {
                            font-size: 14px;
                        }
                        color: $black;
                        font-weight: $font-weight-bold;
                        padding: 0 30px 10px 0;
                        @media #{$xxs-device} {
                            padding: 0 10px 10px 0;
                        }
                    }
                }
                .accordion-content {
                    color: $black-999;
                    font-size: 14px;
                    letter-spacing: 0;
                    line-height: 24px;
                    padding: 0px 30px 9px 16px;
                    display: none;
                    @media #{$xxs-device} {
                        padding: 0 12px 9px 16px;
                    }
                }
            }
        }
    }
}

/*-------- Tab Style Css --------*/

.feature-tab-content {
    .nav {
        &.nav-tabs {
            border-bottom: none;
            margin-bottom: 41px;
            .nav-item {
                margin-right: 60px;
                @media #{$sm-device} {
                    margin-right: 25px;
                }
                @media #{$xs-device} {
                    margin-right: 15px;
                    font-size: 12px;
                }
                .nav-link {
                    border: none;
                    border-bottom: 3px solid $gray-light;
                    color: $black;
                    padding: 0 0 13px;
                    text-transform: uppercase;
                    @include transition(0.3s);
                    &:hover {
                        color: $theme-color;
                    }
                    &:focus {
                        color: $theme-color;
                    }
                    &.active {
                        background-color: transparent;
                        border-bottom-color: $theme-color;
                    }
                }
                &:last-child {
                    margin-right: 0;
                }
            }
        }
    }
    .tab-content {
        .tab-pane {
            p {
                line-height: 30px;
                margin-bottom: 10px;
            }
        }
    }
}

/*-------- Faq Style Css --------*/
.faq-area {
    .accordian-content {
        .accordion {
            .accordion-item {
                border: 1px solid #eaeaea;
                border-radius: 3px;
                margin-bottom: 15px;
                overflow: visible;
                .accordion-header {
                    position: relative;
                    padding: 0;
                    &.active {
                        .accordion-title {
                            color: $theme-color;
                        }
                        &:before {
                            content: "";
                            background-color: $theme-color;
                            background-image: none;
                            border-radius: 3px 3px 0 0;
                            height: 4px;
                            top: -1px;
                            z-index: 1;
                            position: absolute;
                            top: 0;
                            left: 0;
                            width: 100%;
                            transition: all 0.4s;
                        }
                        .opened {
                            display: block !important;
                        }
                        .closed {
                            display: none;
                        }
                    }
                    .accordion-title {
                        display: block;
                        background-color: $white;
                        box-shadow: none;
                        color: $black;
                        transition: all 0.3s ease-in-out;
                        &:hover {
                            color: $theme-color;
                        }
                        font-size: 18px;
                        font-weight: $font-weight-bold;
                        padding: 13px 30px 14px;

                        .icon {
                            color: $theme-color;
                            font-size: 18px;
                            &:hover {
                                color: $theme-color;
                            }
                        }
