/* Import Google Font - Poppins */
@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;600;700&display=swap");

/* Apply Poppins Font Globally */
body {
    font-family: "Poppins", sans-serif;
}

/* Section Styling - Larger & More Spacious */
.section-large {
    min-height: 80vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background-color: #ffffff; /* Light grey background */
    padding-left: 80px;
    padding-right: 60px;
}

/* Stylish Heading */
.stylish-heading {
    font-weight: 700; /* Bold */
    background: linear-gradient(90deg, #00213e, #004080);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

/* Video Styling */
.video-large {
    max-width: 100%;
    border-radius: 15px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}

/* Proper Spacing for Text */
h1 {
    margin-bottom: 24px;
    text-align: left;
}

p {
    font-size: 16px;
    line-height: 1.6;
    margin-bottom: 24px;
}

ul {
    padding-left: 0;
    list-style: none;
}

ul li {
    font-size: 15px;
    margin-bottom: 12px;
    text-align: left;
}

/* Fade-in Animation */
@keyframes fadeIn {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.fade-in {
    opacity: 0;
    animation: fadeIn 1.2s ease-in-out forwards;
}

/* Delayed animations for better effect */
.fade-in:nth-child(1) {
    animation-delay: 0.2s;
}
.fade-in:nth-child(2) {
    animation-delay: 0.4s;
}
.fade-in:nth-child(3) {
    animation-delay: 0.6s;
}
.fade-in:nth-child(4) {
    animation-delay: 0.8s;
}
.fade-in:nth-child(5) {
    animation-delay: 1s;
}
.marquee-container {
    overflow: hidden;
    padding: 20px;
    position: relative;
    text-align: center;
    color: rgb(255, 255, 255);
}

.marquee-heading {
    margin-bottom: 20px;
    font-size: 18px;
}

.marquee-wrapper {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.marquee-content {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.marquee-line {
    display: flex;
    width: max-content;
    animation: scroll-left 25s linear infinite;
}

.strip-2 {
    animation: scroll-right 25s linear infinite;
}

.marquee-logo {
    width: 100px;
    height: auto;
    margin-right: 20px;
}

@keyframes scroll-left {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}

@keyframes scroll-right {
    from {
        transform: translateX(-50%);
    }
    to {
        transform: translateX(0);
    }
}
.count {
    color: #00213e;
    font-family: "Montserrat", sans-serif;
    font-size: clamp(2rem, 5vw, 3.5rem); /* Responsive font size */
    font-weight: bold;
    text-align: center;
    animation: pop-in 5s ease-out forwards;
}

.counter-label {
    color: #ff9900;
    font-size: clamp(1rem, 3vw, 0.15rem); /* Responsive label */
    text-align: center;
    opacity: 0;
    animation: fade-in 1s ease-out forwards 0.2s;
}

.counter-box {
    padding: 5px;
    min-width: 350px; /* Adjusted for better stacking */
    text-align: center;
}

@keyframes pop-in {
    0% {
        transform: scale(0.8);
        opacity: 0;
    }
    100% {
        transform: scale(1);
        opacity: 1;
    }
}

@keyframes fade-in {
    0% {
        opacity: 0;
    }
    100% {
        opacity: 1;
    }
}

